import{_ as a,c as t,o as r,ag as o}from"./chunks/framework.Sr95JMjc.js";const u=JSON.parse('{"title":"연금저축과 노후자금마련","description":"","frontmatter":{"title":"연금저축과 노후자금마련","date":"2025-05-30T23:00+09:00","tags":["연금저축","IRP","ISA","퇴직소득세","연금소득세"]},"headers":[],"relativePath":"investment/raising-funds-for-retirement.md","filePath":"investment/raising-funds-for-retirement.md","lastUpdated":1777630143000}'),n={name:"investment/raising-funds-for-retirement.md"};function i(c,e,d,l,s,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<p>국민 연금(공적 연금) 기금의 고갈 가능성으로 인해 <a href="https://www.youtube.com/watch?v=1ui2ZDJTtOc" target="_blank" rel="noreferrer">국민 연금 개혁안이 통과되면서</a> 92년생부터는 연금 급여액이 줄어들고 MZ 세대들은 <a href="https://www.youtube.com/watch?v=gHpG9_i9YB0" target="_blank" rel="noreferrer">지금보다 더 내면서 덜 받을 수 밖에 없는</a> 상황이다. 그래서 노후 자금 마련에 대해 다른 대안을 미리 준비하는 2030 세대들이 늘어가고 있는 것 같다. 노후 자금 마련을 위한 연금 상품에는 연금저축펀드와 IRP 제도가 있으므로 공부해보도록 하자.</p><h4 id="노후자금마련을-위한-연금저축" tabindex="-1">노후자금마련을 위한 연금저축 <a class="header-anchor" href="#노후자금마련을-위한-연금저축" aria-label="Permalink to &quot;노후자금마련을 위한 연금저축&quot;">​</a></h4><p>연금저축에는 <code>연금저축펀드와 IRP 계좌</code>가 있다. 연금저축은 누구나 개설할 수 있는 기본적인 개인연금 상품이지만 IRP는 근로자나 개인 사업자와 같이 소득이 있는 경우 가입할 수 있는 퇴직연금 상품에 해당된다. 그래서 증권사 앱에서 계좌를 개설할 때 연금저축펀드는 개인연금이고 IRP 계좌는 퇴직연금으로 표시되기도 한다.</p><h4 id="퇴직연금-수령을-위한-irp-계좌" tabindex="-1">퇴직연금 수령을 위한 IRP 계좌 <a class="header-anchor" href="#퇴직연금-수령을-위한-irp-계좌" aria-label="Permalink to &quot;퇴직연금 수령을 위한 IRP 계좌&quot;">​</a></h4><p>2022년부터 회사에서 근로자의 퇴직연금(DB, DC)에 납입해준 퇴직급여를 수령하기 위해서 반드시 IRP 계좌가 필요하다. 개인적으로 납입하던 IRP 계좌가 있더라도 퇴직금 수령을 위한 IRP 계좌를 별도로 개설할 수도 있다. 아무튼, IRP 계좌로 수령받은 퇴직금을 일시금으로 수령하면 퇴직소득세가 과세되고 <code>연금으로 수령하는 경우라면 이연퇴직소득(퇴직소득세의 이연)으로 퇴직소득세의 30%가 감면</code>된다. 또한, 퇴직금이 지급되는 시점의 연금 수령 연차가 11년차 이상이 되면 퇴직소득세의 40%로 감면된다. 따라서, 이연퇴직소득 혜택을 높이고자 한다면 연금 수령을 개시하고나서 10년 동안은 세액공제 받지 않은 적립금으로 지급받을 수 있도록 납입할 수 있다면 좋긴 하다. <a href="https://www.nts.go.kr/nts/cm/cntnts/cntntsView.do?mi=6444&amp;cntntsId=7880" target="_blank" rel="noreferrer">퇴직소득세 계산방법</a>은 생각보다 복잡해보이므로 연금 수령 기간을 적당히 설정하여 연금 수령을 개시해야할 것으로 보인다.</p><blockquote><p>퇴직급여를 IRP 계좌로 의무적으로 수령하는 것으로 바뀐 이유에는 퇴직금을 쉽게 소비하지 않고 연금 자산으로써 활용하기를 권장하기 위함이라고 하더라.</p></blockquote><h4 id="연금저축-매년-납입한도" tabindex="-1">연금저축 매년 납입한도 <a class="header-anchor" href="#연금저축-매년-납입한도" aria-label="Permalink to &quot;연금저축 매년 납입한도&quot;">​</a></h4><p>연금저축펀드와 IRP 계좌에 납입할 수 있는 금액은 모든 연금계좌를 통합하여 <code>매년 1,800만원</code>이다. 따라서, 연금저축 세액공제 혜택을 고려해서 연금저축펀드와 IRP 계좌의 개별 납입한도 설정할 필요가 있다. 초기에는 연금저축펀드 계좌에 납입하는 금액의 비중을 높이고 시간이 지날수록 IRP 계좌의 납입 비중을 조금씩 높여가는 것이 좋다. ISA 계좌 해지 시 이전 납입할 때는 IRP 계좌보다는 중도 인출이 가능한 연금저축펀드로 납입하는 걸 고려하는게 괜찮을 것 같다.</p><h4 id="연금저축-세액공제" tabindex="-1">연금저축 세액공제 <a class="header-anchor" href="#연금저축-세액공제" aria-label="Permalink to &quot;연금저축 세액공제&quot;">​</a></h4><p>연금저축펀드와 IRP 계좌에 납입하는 금액 중에서<code>연금저축 계좌 납입에 따라 매년 600만원 또는 900만원의 세액 공제 혜택을 제공</code>한다. 기본적인 공제 세율은 16.5% 이지만 총급여 5,500만원을 넘는 고소득자들은 13.2% 만큼만 공제해준다.</p><ul><li>연금저축계좌 : 최대 600만원</li><li>IRP : 최대 900만원</li><li>연금저축 + IRP 계좌 : 최대 900만원 (연금저축 600만원 + IRP 300만원)</li></ul><p>연말정산 시 세액공제 납입 한도는 연금계좌 통합 기준이므로 세액 공제를 최대한 받을 수 있도록 납입할 필요가 있다. 다만, 연금저축은 IRP 계좌와 다르게 중도인출이 가능하기 때문에 <code>세액공제를 받지 않은 금액은 언제든지 인출이 가능하다</code>는 차이가 있다.</p><h4 id="세액공제-받은-금액의-중도-인출" tabindex="-1">세액공제 받은 금액의 중도 인출 <a class="header-anchor" href="#세액공제-받은-금액의-중도-인출" aria-label="Permalink to &quot;세액공제 받은 금액의 중도 인출&quot;">​</a></h4><p>연금저축펀드에 납인한 금액 중에서 세액공제 받지 않은 금액은 언제든지 인출이 가능하다고 했다. 그러나, 연말정산 시 이미 <code>세액공제를 받은 금액까지 인출하려면 세액공제 받았던 만큼 기타소득세로 16.5%를 과세</code>한다. 만약, 총급여 5,500만원 이상이라면 13.2%로 세액공제를 받았기에 받은 혜택보다 더 내야하는 상황이 된다. 아무튼, 중단기적으로 중도 인출 가능성이 높은 2030 세대들에게는 <code>IRP 보다는 연금저축펀드에 주로 납입하는게 좋을 수</code> 있다.</p><h4 id="연금수령-시-연금소득세" tabindex="-1">연금수령 시 연금소득세 <a class="header-anchor" href="#연금수령-시-연금소득세" aria-label="Permalink to &quot;연금수령 시 연금소득세&quot;">​</a></h4><p>연금저축으로 <code>납입한 금액과 운용 수익은 만 55세 이후부터 최소 10년동안 연금 수령을 개시</code>할 수 있다. 연금수령 시 세액공제를 받지 않은 금액과 퇴직금을 모두 지급받은 이후에는 세액공제를 받은 적립금과 투자를 통해 벌어들인 운용 수익을 지급받는다. 이때, 매년 <code>연금 수령액이 1,500만원을 넘지 않으면 연금소득세 5.5%로 저율 과세</code>된다. 사적연금(세액공제 받은 금액과 운용 수익)을 수령하는 경우 <a href="https://www.youtube.com/watch?v=D-RWPF0HSzg" target="_blank" rel="noreferrer">1,500만원을 초과하면 다른 소득과 함께 종합소득 과세 대상</a>이 되므로 주의해야한다.</p><blockquote><p>연금저축(사적연금)은 연금 수령할 경우 국민연금(공적연금)과 다르게 운용 수익이 건강보험료에 적용되지 않는다.</p></blockquote><h4 id="isa-계좌-이전-납입-시-추가-세액공제" tabindex="-1">ISA 계좌 이전 납입 시 추가 세액공제 <a class="header-anchor" href="#isa-계좌-이전-납입-시-추가-세액공제" aria-label="Permalink to &quot;ISA 계좌 이전 납입 시 추가 세액공제&quot;">​</a></h4><p>ISA 계좌를 해지하고 <code>연금저축 계좌에 이전 납입한 금액의 10%에 대해 추가적인 세액공제 한도(최대 300만원)를 제공</code>한다. ISA 계좌의 적립금 중 3천만원까지 납입하면 세제 혜택을 최대로 받을 수 있다는 이야기다. 현재 납입을 시작한 ISA 계좌를 해지할 때에는 투자한 자금을 모두 회수하여 사용해야할 가능성이 높아서 청년도약계좌가 만기되는 시점을 지나 다음번 운용하는 ISA 계좌가 해지될 때는 연금저축계좌에 납입하는 것을 고려해야할 것 같다.</p><h4 id="연금저축-적립금으로-tdf-투자" tabindex="-1">연금저축 적립금으로 TDF 투자 <a class="header-anchor" href="#연금저축-적립금으로-tdf-투자" aria-label="Permalink to &quot;연금저축 적립금으로 TDF 투자&quot;">​</a></h4><p>연금저축으로 납입하는 적립금은 펀드 또는 ETF 상품에 투자할 수 있다. ISA 계좌처럼 채권 또는 주식형 ETF 상품에 투자하기 보다는 <a href="https://www.youtube.com/watch?v=qk1unjHKjkQ" target="_blank" rel="noreferrer">자산운용사가 알아서 은퇴 시점에 맞추어 주식과 채권의 비중을 조절하는 TDF</a>로 투자해두고 ISA 계좌 운용에 집중하는게 좋을 것 같다. 일단, 매월 근로 소득 중 각 5만원씩 입금되도록 자동이체 설정해두었으니 앞으로 적금 납입 금액을 줄이면서 조금씩 연금저축펀드와 IRP 계좌에 납입하는 금액을 늘려가면 된다. <code>만 40세부터는 적극적으로 납입하여 운용하지 않을까?</code></p><hr><p>조금 과장되게 말해서 안정적인 노후 생활비를 연금으로 수령하기 위해서는 최소 5억원에서 10억원이 필요하다고 말한다. 주로 부동산을 자산으로 소유하고 있는 기성세대들이 아니고서야 <a href="https://toss.im/tossfeed/article/retirement-plans-02" target="_blank" rel="noreferrer">10억원이라는 거액의 노후 자금을 마련</a>할 수 있는 청년들이 얼마나 있을까 궁금하다. 아무튼, <a href="https://www.youtube.com/watch?v=EohbxcEnCYw" target="_blank" rel="noreferrer">노후자금마련 및 노후 준비는 가능한 빨리 시작하는 것이 좋다</a>고 하니 신입 개발자로 시작하는 사람들은 상대적으로 고소득자가 될 가능성이 높으므로 <code>주택청약통장 보다는 연금저축계좌에 납입</code>하는 걸 추천한다.</p>',23)])])}const f=a(n,[["render",i]]);export{u as __pageData,f as default};
